/* Example: styling a container */
div {
  width: 100%;
  padding: 20px;
  background-color: #f0f0f0;
}

/* Example: creating two columns for a section */
.section-content {
  columns: 2;
}

/* Example: setting a fixed column width */
.container {
  column-width: 200px;
}

/* Similar: using column-count for fixed columns */
.container {
  column-count: 4;
}

/* Similar: adding gap between columns */
.container {
  columns: 3;
  column-gap: 2em;
}

/* Example: adding a column rule */
.container {
  columns: 3;
  column-gap: 20px;
  column-rule: 1px dashed gray;
}

/* Prevent list items from breaking across columns */
li {
  break-inside: avoid;
}

/* Example: making a heading span columns */
h2 {
  column-span: all;
  text-align: center;
}

/* Example: columns shorthand with width and count */
.container {
  columns: 150px 4;
}
